# Initialize the best allocation and its fairness
best_allocation = None
best_fairness = float('inf')

# Helper function to calculate fairness
def calculate_fairness(allocation):
    total_values = {p: sum(values[p].get(g, 0) for g in allocation[p]) for p in allocation}
    return max(total_values.values()) - min(total_values.values())

# Iterate over all possible allocations
for perm in permutations(goods, len(goods)):
    allocation = {1: [], 2: [], 3: []}
