        allocation[people[i % 3]].append(perm[i])

    fairness = calculate_fairness(allocation)
    if fairness < best_fairness:
        best_fairness = fairness
        best_allocation = allocation

print("Best Allocation:")
for person, items in best_allocation.items():
    print(f"Person {person}: {items}")
