```python
from itertools import permutations

def allocate_goods(values):
    people = list(values.keys())
    goods = list(values[people[0]].keys())
    max_value = -1
    best_allocation = None

    # Generate all possible allocations (permutations of goods to people)
    for allocation in permutations(people * len(goods), len(goods)):
        if (len(set(allocation[:len(goods)])) != len(allocation[:len(goods)])):
            continue  # Ensure each good is given to a different person or thrown away

        allocation_value = 0
        allocation_details = {person: [] for person in people}

        for good, person in zip(goods, allocation[:len(goods)]):
            allocation_value += values[person][good]
            allocation_details[person].append(good)

        if allocation_value > max_value:
            max_value = allocation_value
            best_allocation = allocation_details

    return best_allocation

# Values for each person and good
values = {
    "Person 1": {"A": 5, "B": 47, "C": 45, "D": 3},
    "Person 2": {"A": 45, "B": 5, "C": 48, "D": 2},
    "Person 3": {"A": 23, "B": 25, "C": 32, "D": 20}
}

allocation = allocate_goods(values)
print(allocation)
```

