```python
# Define the values for each person
values = {
    "Person 1": {"A": 5, "B": 47, "C": 45, "D": 3},
    "Person 2": {"A": 45, "B": 5, "C": 48, "D": 2},
    "Person 3": {"A": 23, "B": 25, "C": 32, "D": 20}
}

# Store the allocation
allocation = {"Person 1": [], "Person 2": [], "Person 3": []}

# Function to find the fairest allocation
def allocate_goods(values):
    allocated = set()

    # Sort the goods for each person by their values
    sorted_values = {
        person: sorted(goods.items(), key=lambda item: item[1], reverse=True)
        for person, goods in values.items()
    }

    # Prioritize goods by highest value for each person
    priority_list = sorted(
        [(person, good, value) for person, goods in sorted_values.items() for good, value in goods],
        key=lambda item: item[2],
        reverse=True
    )

    for person, good, value in priority_list:
        if good not in allocated:
            allocation[person].append(good)
            allocated.add(good)

    return allocation

# Allocate the goods and print the result
print(allocate_goods(values))
```

