```python
import itertools

# Define the valuations in a dictionary format.
valuations = {
    'Person 1': {'A': 5, 'B': 47, 'C': 45, 'D': 3},
    'Person 2': {'A': 45, 'B': 5, 'C': 48, 'D': 2},
    'Person 3': {'A': 23, 'B': 25, 'C': 32, 'D': 20}
}

goods = ['A', 'B', 'C', 'D']
people = ['Person 1', 'Person 2', 'Person 3']

def find_best_allocation(valuations, goods, people):
    # Generate all possible allocations
    all_allocations = itertools.product(people + ['None'], repeat=len(goods))

    best_allocation = None
    best_value = -float('inf')

    for allocation in all_allocations:
        total_value = 0
        for good, person in zip(goods, allocation):
            if person != 'None':
                total_value += valuations[person][good]

        # We're looking for the allocation that maximizes the total value
        if total_value > best_value:
            best_value = total_value
            best_allocation = allocation

    result = {}
    for good, person in zip(goods, best_allocation):
        if person != 'None':
            if person not in result:
                result[person] = []
            result[person].append(good)

    return result

# Find the fair allocation
allocation_result = find_best_allocation(valuations, goods, people)

# Output the result
print("Fair allocation:")
for person, goods in allocation_result.items():
    print(f"{person}: {', '.join(goods)}")
```

Running this code provides the allocation based on maximizing the overall value for each person given the valuations for each good. This approach ensures that the chosen allocation maximizes collective benefit.

